package portfolio.week08;
import javafx.application.Application; import javafx.beans.property.SimpleStringProperty; import javafx.beans.property.StringProperty; import javafx.beans.binding.Bindings; import javafx.scene.Scene; import javafx.scene.control.*; import javafx.scene.layout.VBox; import javafx.stage.Stage;
public class BindingDemo extends Application { public void start(Stage s){ StringProperty model=new SimpleStringProperty(); TextField input=new TextField(); Label mirror=new Label(); mirror.textProperty().bind(model); input.textProperty().bindBidirectional(model); Label count=new Label(); count.textProperty().bind(Bindings.concat("Characters: ", model.length())); VBox box=new VBox(10,input,mirror,count); box.setPadding(new javafx.geometry.Insets(18)); s.setScene(new Scene(box,400,160)); s.setTitle("Reactive model"); s.show(); } public static void main(String[] a){launch(a);} }
